const cleanedUsers = $input.all()
  .filter(item => item.json.name.trim() !== "")
  .map(item => {

    const name = item.json.name
      .trim()
      .toLowerCase();

    const cleanName =
      name.charAt(0).toUpperCase() +
      name.slice(1);

    const cleanEmail =
      item.json.email
        .trim()
        .toLowerCase();

    return {
      json: {
        name: cleanName,
        email: cleanEmail
      }
    };
  });

return cleanedUsers;
